// API Gateway / Reverse proxy routing
app.MapReverseProxy();

// Or ASP.NET Core YARP\n    builder.Services.AddReverseProxy()
    .LoadFromConfig("ReverseProxy");

// In appsettings.json
{
  "ReverseProxy": {
    "Routes": {
      "orders-route": {
        "ClusterId": "orders-cluster",
        "MatchPath": "/api/orders/**"
      }
    },
    "Clusters": {
      "orders-cluster": {
        "Destinations": {
          "legacy": { "Address": "http://monolith/" },
          "service": { "Address": "http://orders-service/" }
        }
      }
    }
  }
}
